  "Se qualquer humano responder no WhatsApp durante a espera ou aprovação, a sugestão da IA é cancelada na hora.": ["If any human agent replies on WhatsApp during the wait or approval window, the AI suggestion is immediately cancelled.", "Si cualquier humano responde en WhatsApp durante la espera o aprobación, la sugerencia de la IA se cancela al instante."],
