  "Prioridade Humana & Agrupamento Inteligente": ["Human Priority & Smart Message Grouping", "Prioridad Humana y Agrupación Inteligente"],
  "Evita que o agente e o atendente humano compitam ou respondam às mesmas mensagens no WhatsApp/Chatwoot.": ["Prevents the AI agent and human support agents from colliding or replying to the same WhatsApp/Chatwoot messages.", "Evita que el agente y el operador humano compitan o respondan a los mismos mensajes en WhatsApp/Chatwoot."],
  "Aguarda 3 min em novas conversas antes de sugerir resposta e pausa automaticamente a IA por 4h se um atendente humano responder no WhatsApp.": ["Waits 3 min on new conversations before suggesting a reply and automatically pauses AI for 4h if a human agent replies on WhatsApp.", "Espera 3 min en nuevas conversaciones antes de sugerir respuesta y pausa automáticamente la IA por 4h si un humano responde en WhatsApp."],
  "Aprovações & Autonomia dos Agentes": ["Agent Approvals & Autonomy", "Aprobaciones y Autonomía de los Agentes"],
