  "Hierarquia de Execução:": ["Execution Hierarchy:", "Jerarquía de Ejecución:"],
  "Cada agente da sua árvore (COO, CFO, Gestor de Estoque, etc.) executa com o modelo específico configurado no seu próprio bloco no Studio. A seleção acima atua como padrão de contingência (chat direto e rotinas não atribuídas) e alimenta o simulador dinâmico de custos abaixo.": ["Each agent in your hierarchy (COO, CFO, Inventory Manager, etc.) runs with the specific model configured on its own block in the Studio. The selection above acts as the contingency default (direct chat and unassigned routines) and powers the dynamic cost simulator below.", "Cada agente de su árbol (COO, CFO, Gestor de Inventario, etc.) se ejecuta con el modelo específico configurado en su propio bloque del Studio. La selección anterior actúa como respaldo predeterminado y alimenta el simulador dinámico de costos."],
