  ". Acesso nativo para pesquisar manuais, receitas, POPs e planilhas operacionais.": [". Native access to search manuals, recipes, SOPs, and operational spreadsheets.", ". Acceso nativo para buscar manuales, recetas, POEs y hojas de cálculo operativas."],
