  "1. Responda DIRETAMENTE ao que foi solicitado logo na primeira linha, sem enrolação ou preâmbulos.\\n": ["1. Answer DIRECTLY what was requested right on the first line, without fluff or preambles.\\n", "1. Responda DIRECTAMENTE a lo solicitado desde la primera línea, sin rodeos ni preámbulos.\\n"],
