  "2. Decisão Estratégica do Comitê": ["2. Strategic Committee Decision", "2. Decisión Estratégica del Comité"],
  "2. Se a pergunta solicitar dados, lista, nomes, horários ou tabelas (ex: colaboradores escalados, valores de venda, canais, estoque), apresente DIRETAMENTE a tabela/dados solicitados em Markdown limpo e bem formatado.\\n": ["2. If the question requests data, lists, names, schedules, or tables (e.g., scheduled employees, sales figures, channels, inventory), present DIRECTLY the requested table/data in clean, well-formatted Markdown.\\n", "2. Si la pregunta solicita datos, listas, nombres, horarios o tablas (ej.: colaboradores programados, valores de venta, canales, inventario), presente DIRECTAMENTE la tabla/datos solicitados en Markdown limpio y bien formateado.\\n"],
