  "O Gestor Web possui apenas 1 licença de acesso simultâneo. Para proteger o caixa físico da loja durante o expediente, as consultas automatizadas ocorrem à noite (22h30 às 08h30), e durante o dia as consultas de produtos e preços são feitas diretamente via ERP (Classe Delivery).": ["The Web Manager has only 1 concurrent access license. To protect the store's physical POS during business hours, automated queries run overnight (10:30 PM to 8:30 AM), and daytime product and price queries are performed directly via ERP (Delivery Class).", "El Gestor Web posee solo 1 licencia de acceso simultáneo. Para proteger la caja física de la tienda durante el horario comercial, las consultas automatizadas se realizan por la noche (22:30 a 08:30), y durante el día las consultas de productos y precios se hacen directamente vía ERP (Clase Delivery)."],
  "O agente retém o histórico de consultas e métricas aprendidas nas interações recentes.": ["The agent retains query history and metrics learned from recent interactions.", "El agente conserva el historial de consultas y métricas aprendidas en las interacciones recientes."],
