  "✓ O gatilho iFood escuta eventos e novos pedidos diretamente via sessão autenticada do Portal do Parceiro (portal.ifood.com.br) e retaguarda no Radar ERP, sem necessidade de CNAE de tecnologia no CNPJ da empresa.": ["✓ The iFood trigger listens to events and new orders directly via an authenticated Partner Portal session (portal.ifood.com.br) and ERP Radar backoffice, without requiring a technology industry code (CNAE) on the company's tax registration.", "✓ El disparador de iFood escucha eventos y nuevos pedidos directamente mediante la sesión autenticada del Portal de Socios (portal.ifood.com.br) y el backoffice en el Radar ERP, sin necesidad de código de actividad tecnológica (CNAE) en el registro fiscal de la empresa."],
