  "Roteamento FinOps: Migrar 'Apuração de Resultados & CMV' para Gemini 3.1 Flash-Lite": ["FinOps Routing: Migrate 'P&L & COGS Analyst' to Gemini 3.1 Flash-Lite", "Enrutamiento FinOps: Migrar 'Análisis de Resultados y CMV' a Gemini 3.1 Flash-Lite"],
